import * as React from "react";
import { graphql, type HeadFC, type PageProps } from "gatsby";
import Layout from "../components/layout";
import { UserProfile } from "../interfaces";
import data from "../data/data.json";
import Products from "../components/products";
import Carousel from "../components/carousel";
import images from "../images";
import { useTranslation } from "gatsby-plugin-react-i18next";

const IndexPage: React.FC<PageProps> = () => {
  const userData: UserProfile = data;
  const { t } = useTranslation();
  const carouselImages = [
    { src: images.yellow.src, alt: images.yellow.alt },
    { src: images.red.src, alt: images.red.alt },
    { src: images.fall.src, alt: images.fall.alt },
    { src: images.pink.src, alt: images.pink.alt },
  ];

  const textOverlay = [
    { content: t("carousel.text_1") },
    { content: t("carousel.text_2") },
    { content: t("carousel.text_3") },
    { content: t("carousel.text_4") },
  ];
  return (
    <Layout data={userData}>
      <Carousel
        images={carouselImages}
        textOverlay={textOverlay}
        speed={6000}
      />
      <Products />
    </Layout>
  );
};

export default IndexPage;

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;
