import React, { useContext, useState } from "react";
import { CartContext } from "../context/cartContext";
import data from "../data/data.json";
import { Link } from "gatsby";
import { useTranslation } from "gatsby-plugin-react-i18next";
import images from "../images";
import { Product } from "../interfaces";

const ProductPage = () => {
  const { t } = useTranslation();
  const cartContext = useContext(CartContext);
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);

  if (!cartContext) {
    return <div>{t("cart.cartContextError")}</div>;
  }

  const { addToCart, cart } = cartContext;
  const products = data.products;
  const totalItems = cart.reduce((sum, item) => sum + item.quantity, 0);

  return (
    <div className="container mx-auto p-4">
      {/* Encabezado con botón de acceso al carrito */}
      <div className="flex justify-between items-center mb-4">
        <h1 className="text-2xl font-bold">{t("cart.products")}</h1>
        <Link to="/cart" className="relative bg-gray-800 text-white px-4 py-2 rounded">
          🛒 {t("cart.cart")} ({totalItems})
        </Link>
      </div>

      {/* Grid de productos con overlay */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {products.map((product) => (
          <div
            key={product.id}
            className="relative cursor-pointer overflow-hidden rounded-lg"
            onClick={() => setSelectedProduct({ ...product, quantity: 1 })}
          >
            <img
              src={`${images[product.image].src}`}
              alt={`${images[product.image].alt}`}
              className="w-full h-64 object-cover"
            />
            <div className="absolute inset-0 bg-black bg-opacity-50 flex flex-col justify-end p-4 text-white">
              <h2 className="text-lg font-semibold">{product.name}</h2>
              <p className="text-gray-200">${product.price}</p>
            </div>
          </div>
        ))}
      </div>

      {/* Modal de detalles del producto */}
      {selectedProduct && (
        <div className="fixed inset-0 flex items-center justify-center bg-black bg-opacity-75">
          <div className="bg-white p-6 rounded-lg shadow-lg max-w-md w-full relative">
            <button
              className="absolute top-2 right-2 text-gray-600 hover:text-gray-900"
              onClick={() => setSelectedProduct(null)}
            >
              ✖
            </button>
            <img
              src={`${images[selectedProduct.image].src}`}
              alt={`${images[selectedProduct.image].alt}`}
              className="w-full h-64 object-cover rounded"
            />
            <h2 className="text-2xl font-semibold mt-4">{selectedProduct.name}</h2>
            <p className="text-gray-700 my-2">${selectedProduct.price}</p>
            <button
              className="mt-4 bg-blue-500 text-white px-4 py-2 rounded w-full"
              onClick={() => {
                addToCart({ ...selectedProduct, quantity: 1 });
                setSelectedProduct(null);
              }}
            >
              {t("cart.addToCart")}
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default ProductPage;
